<body>
  <main class="support-shell">
    <section class="support-card" aria-labelledby="support-title">
      <p class="eyebrow">Support</p>
      <h1 id="support-title">Contact our team</h1>
      <p class="subtitle">Send a message and we'll get back to you as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name</label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            placeholder="Jane Doe"
            required
          />
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address</label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            placeholder="jane@company.com"
            required
          />
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            placeholder="+1 (555) 123-4567"
            aria-describedby="phone-help phone-error"
          />
          <p class="helper-text" id="phone-help">Optional. Use the format +1 (555) 123-4567.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <div class="actions">
          <button type="submit">Submit request</button>
        </div>

        <div class="status" id="form-status" role="status" aria-live="polite"></div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error')
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error')
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error')
      }
    };

    const phonePattern = /^\+1 \(\d{3}\) \d{3}-\d{4}$/;

    function setError(field, message) {
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
      field.error.textContent = message;
    }

    function validateFullName() {
      const value = fields.fullName.input.value.trim();
      if (!value) {
        setError(fields.fullName, 'Full name is required.');
        return false;
      }
      setError(fields.fullName, '');
      return true;
    }

    function validateEmail() {
      const value = fields.email.input.value.trim();
      if (!value) {
        setError(fields.email, 'Email address is required.');
        return false;
      }

      if (!fields.email.input.checkValidity()) {
        setError(fields.email, 'Enter a valid email address.');
        return false;
      }

      setError(fields.email, '');
      return true;
    }

    function validatePhone() {
      const value = fields.phone.input.value.trim();
      if (!value) {
        setError(fields.phone, '');
        return true;
      }

      if (!phonePattern.test(value)) {
        setError(fields.phone, 'Use +1 (555) 123-4567.');
        return false;
      }

      setError(fields.phone, '');
      return true;
    }

    function validateForm() {
      const valid = [
        validateFullName(),
        validateEmail(),
        validatePhone()
      ].every(Boolean);

      return valid;
    }

    ['input', 'blur'].forEach((eventName) => {
      fields.fullName.input.addEventListener(eventName, validateFullName);
      fields.email.input.addEventListener(eventName, validateEmail);
      fields.phone.input.addEventListener(eventName, validatePhone);
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.classList.remove('is-visible');
      status.textContent = '';

      if (!validateForm()) {
        return;
      }

      status.textContent = 'Thanks — your request has been submitted.';
      status.classList.add('is-visible');
      form.reset();
      Object.values(fields).forEach((field) => setError(field, ''));
    });
  </script>
</body>
</html>
