 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --card: #ffffff;
       --text: #142033;
       --muted: #667085;
       --border: #d9e1ec;
       --primary: #2563eb;
       --primary-dark: #1d4ed8;
