       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 35%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 32px 16px;
